 static int assertions;
 static void verify(boolean condition,String message){if(!condition)throw new AssertionError(message);assertions++;}
 static Map<String,Object> get(String base,String token,String id)throws Exception{return assign(base,token,"EO_GET",mapOf("contestId",id));}
