 static Map<String,Object> draft(String base,String token,Map<String,Object> doc)throws Exception{return assign(base,token,"EO_DRAFT_SAVE",mapOf("document",doc));}
 static Map<String,Object> schedule(String base,String token,Map<String,Object> draft)throws Exception{return assign(base,token,"EO_SCHEDULE",mapOf("draftId",draft.get("id"),"expectedRevision",draft.get("revision")));}
 static void control(String base,String token,String id,String action,Map<String,Object> options)throws Exception{var req=new LinkedHashMap<>(options);req.putAll(mapOf("contestId",id,"expectedRevision",exam(base,token,id).get("revision"),"action",action,"reason","Integration test: "+action));assign(base,token,"EO_CONTROL",req);}
 static void sql(Path learning,String sql,Object... args)throws Exception{try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+learning.toAbsolutePath());PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);p.executeUpdate();}}
