   control(base,t,id,"LOCK",mapOf("locked",true));verify(send(base,s,"CONTEST_SUBMIT",mapOf("contestId",id,"exerciseId",q,"sourceCode","public class Main {}","idempotencyKey","locked")).status()!=200,"locked exam rejects receipt");control(base,t,id,"LOCK",mapOf("locked",false));
   List<CompletableFuture<Response>> requests=new ArrayList<>();for(int i=0;i<4;i++){final String key="concurrent-"+i;requests.add(CompletableFuture.supplyAsync(()->{try{return send(base,s,"CONTEST_SUBMIT",mapOf("contestId",id,"exerciseId",q,"sourceCode","public class Main {}","idempotencyKey",key));}catch(Exception ex){throw new CompletionException(ex);}}));}List<String> accepted=new ArrayList<>();for(var request:requests){var r=request.get();if(r.status()==200)accepted.add(text(obj(obj(r.body().get("data")).get("submission")),"id",""));}verify(accepted.size()==2,"concurrent requests cannot exceed two-attempt quota");
   AssignmentRepository repo=new AssignmentRepository(learning);for(String sid:accepted){long limit=System.currentTimeMillis()+15000;while(!repo.getContestSubmission(sid).status().equals("DONE")&&System.currentTimeMillis()<limit)Thread.sleep(100);verify(repo.getContestSubmission(sid).status().equals("DONE"),"worker finishes receipt");repo.saveContestSubmissionResult(sid,new GradingResult("AC",50,50,2,2,"settled grading fixture",100,List.of()));}String sid=accepted.getFirst();savedSubmission=sid;
   var hidden=obj(assign(base,s,"CONTEST_SUBMISSION_RESULT",mapOf("submissionId",sid)).get("submission"));verify(hidden.get("score")==null&&"HIDDEN".equals(hidden.get("verdict"))&&list(hidden.get("testResults")).isEmpty(),"legacy result path obeys unpublished policy");verify(rows(get(base,s,id).get("submissions")).stream().allMatch(r->r.get("score")==null),"organization API hides unpublished results");verify(send(base,p,"EO_GET",mapOf("contestId",id)).status()!=200,"other teacher cannot see grading feedback");
