   assign(base,t,"EO_PUBLISH",mapOf("contestId",id));verify(number(obj(assign(base,s,"CONTEST_SUBMISSION_RESULT",mapOf("submissionId",sid)).get("submission")),"score",-1)==50,"publication releases result through every API");
